95	void StorageFileLog::loadMetaFiles(bool attach)
96	{
97	    /// Attach table
98	    if (attach)
99	    {
100	        const auto & storage = getStorageID();
101	
102	        auto metadata_path_exist = std::filesystem::exists(metadata_base_path);
103	        auto previous_path = std::filesystem::path(getContext()->getPath()) / ".filelog_storage_metadata" / storage.getDatabaseName() / storage.getTableName();
104	
105	        /// For compatibility with the previous path version.
106	        if (std::filesystem::exists(previous_path) && !metadata_path_exist)
107	        {
108	            std::filesystem::copy(previous_path, metadata_base_path, std::filesystem::copy_options::recursive);
109	            std::filesystem::remove_all(previous_path);
110	        }
111	        /// Meta file may lost, log and create directory
112	        else if (!metadata_path_exist)
113	        {
114	            /// Create metadata_base_path directory when store meta data
115	            LOG_ERROR(log, "Metadata files of table {} are lost.", getStorageID().getTableName());
116	        }
117	        /// Load all meta info to file_infos;
118	        deserialize();
119	    }
120	    /// Create table, just create meta data directory
121	    else
122	    {
123	        if (std::filesystem::exists(metadata_base_path))
124	        {
125	            throw Exception(
126	                ErrorCodes::TABLE_METADATA_ALREADY_EXISTS,
127	                "Metadata files already exist by path: {}, remove them manually if it is intended",
128	                metadata_base_path);
129	        }
130	        /// We do not create the metadata_base_path directory at creation time, create it at the moment of serializing
131	        /// meta files, such that can avoid unnecessarily create this directory if create table failed.
132	    }
133	}
