135	void StorageFileLog::loadFiles()
136	{
137	    if (!fileOrSymlinkPathStartsWith(path, getContext()->getUserFilesPath()))
138	    {
139	        throw Exception(
140	            ErrorCodes::BAD_ARGUMENTS, "The absolute data path should be inside `user_files_path`({})", getContext()->getUserFilesPath());
141	    }
142	
143	    auto absolute_path = std::filesystem::absolute(path);
144	    absolute_path = absolute_path.lexically_normal(); /// Normalize path.
145	
146	    if (std::filesystem::is_regular_file(absolute_path))
147	    {
148	        path_is_directory = false;
149	        root_data_path = absolute_path.parent_path();
150	
151	        file_infos.file_names.push_back(absolute_path.filename());
152	    }
153	    else if (std::filesystem::is_directory(absolute_path))
154	    {
155	        root_data_path = absolute_path;
156	        /// Just consider file with depth 1
157	        for (const auto & dir_entry : std::filesystem::directory_iterator{absolute_path})
158	        {
159	            if (dir_entry.is_regular_file())
160	            {
161	                file_infos.file_names.push_back(dir_entry.path().filename());
162	            }
163	        }
164	    }
165	    else
166	    {
167	        throw Exception(ErrorCodes::BAD_ARGUMENTS, "The path {} neither a regular file, nor a directory", absolute_path.c_str());
168	    }
169	
170	    /// Get files inode
171	    for (const auto & file : file_infos.file_names)
172	    {
173	        auto inode = getInode(getFullDataPath(file));
174	        file_infos.context_by_name.emplace(file, FileContext{.inode = inode});
175	    }
176	
177	    /// Update file meta or create file meta
178	    for (const auto & [file, ctx] : file_infos.context_by_name)
179	    {
180	        if (auto it = file_infos.meta_by_inode.find(ctx.inode); it != file_infos.meta_by_inode.end())
181	        {
182	            /// data file have been renamed, need update meta file's name
183	            if (it->second.file_name != file)
184	            {
185	                std::filesystem::rename(getFullMetaPath(it->second.file_name), getFullMetaPath(file));
186	                it->second.file_name = file;
187	            }
188	        }
189	        /// New file
190	        else
191	        {
192	            FileMeta meta{file, 0, 0};
193	            file_infos.meta_by_inode.emplace(ctx.inode, meta);
194	        }
195	    }
196	
197	    /// Clear unneeded meta file, because data files may be deleted
198	    if (file_infos.meta_by_inode.size() > file_infos.context_by_name.size())
199	    {

200	        InodeToFileMeta valid_metas;
201	        valid_metas.reserve(file_infos.context_by_name.size());
202	        for (const auto & [inode, meta] : file_infos.meta_by_inode)
203	        {
204	            /// Note, here we need to use inode to judge does the meta file is valid.
205	            /// In the case that when a file deleted, then we create new file with the
206	            /// same name, it will have different inode number with stored meta file,
207	            /// so the stored meta file is invalid
208	            if (auto it = file_infos.context_by_name.find(meta.file_name);
209	                it != file_infos.context_by_name.end() && it->second.inode == inode)
210	                valid_metas.emplace(inode, meta);
211	            /// Delete meta file from filesystem
212	            else
213	                std::filesystem::remove(getFullMetaPath(meta.file_name));
214	        }
215	        file_infos.meta_by_inode.swap(valid_metas);
216	    }
217	}
