219	void StorageFileLog::serialize() const
220	{
221	    if (!std::filesystem::exists(metadata_base_path))
222	    {
223	        std::filesystem::create_directories(metadata_base_path);
224	    }
225	    for (const auto & [inode, meta] : file_infos.meta_by_inode)
226	    {
227	        auto full_name = getFullMetaPath(meta.file_name);
228	        if (!std::filesystem::exists(full_name))
229	        {
230	            FS::createFile(full_name);
231	        }
232	        else
233	        {
234	            checkOffsetIsValid(full_name, meta.last_writen_position);
235	        }
236	        WriteBufferFromFile out(full_name);
237	        writeIntText(inode, out);
238	        writeChar('\n', out);
239	        writeIntText(meta.last_writen_position, out);
240	    }
241	}
