264	void StorageFileLog::deserialize()
265	{
266	    if (!std::filesystem::exists(metadata_base_path))
267	        return;
268	    /// In case of single file (not a watched directory),
269	    /// iterated directory always has one file inside.
270	    for (const auto & dir_entry : std::filesystem::directory_iterator{metadata_base_path})
271	    {
272	        if (!dir_entry.is_regular_file())
273	        {
274	            throw Exception(
275	                ErrorCodes::BAD_FILE_TYPE,
276	                "The file {} under {} is not a regular file when deserializing meta files",
277	                dir_entry.path().c_str(),
278	                metadata_base_path);
279	        }
280	
281	        ReadBufferFromFile in(dir_entry.path().c_str());
282	        FileMeta meta;
283	        UInt64 inode, last_written_pos;
284	
285	        if (!tryReadIntText(inode, in))
286	        {
287	            throw Exception(ErrorCodes::CANNOT_READ_ALL_DATA, "Read meta file {} failed", dir_entry.path().c_str());
288	        }
289	        assertChar('\n', in);
290	        if (!tryReadIntText(last_written_pos, in))
291	        {
292	            throw Exception(ErrorCodes::CANNOT_READ_ALL_DATA, "Read meta file {} failed", dir_entry.path().c_str());
293	        }
294	
295	        meta.file_name = dir_entry.path().filename();
296	        meta.last_writen_position = last_written_pos;
297	
298	        file_infos.meta_by_inode.emplace(inode, meta);
299	    }
300	}
