312	Pipe StorageFileLog::read(
313	    const Names & column_names,
314	    const StorageSnapshotPtr & storage_snapshot,
315	    SelectQueryInfo & /* query_info */,
316	    ContextPtr local_context,
317	    QueryProcessingStage::Enum /* processed_stage */,
318	    size_t /* max_block_size */,
319	    unsigned /* num_streams */)
320	{
321	    /// If there are MVs depended on this table, we just forbid reading
322	    if (!local_context->getSettingsRef().stream_like_engine_allow_direct_select)
323	        throw Exception(ErrorCodes::QUERY_NOT_ALLOWED, "Direct select is not allowed. To enable use setting `stream_like_engine_allow_direct_select`");
324	
325	    if (mv_attached)
326	        throw Exception(ErrorCodes::QUERY_NOT_ALLOWED, "Cannot read from StorageFileLog with attached materialized views");
327	
328	    std::lock_guard<std::mutex> lock(file_infos_mutex);
329	    if (running_streams)
330	    {
331	        throw Exception("Another select query is running on this table, need to wait it finish.", ErrorCodes::CANNOT_SELECT);
332	    }
333	
334	    updateFileInfos();
335	
336	    /// No files to parse
337	    if (file_infos.file_names.empty())
338	    {
339	        LOG_WARNING(log, "There is a idle table named {}, no files need to parse.", getName());
340	        return Pipe{};
341	    }
342	
343	    auto modified_context = Context::createCopy(local_context);
344	
345	    auto max_streams_number = std::min<UInt64>(filelog_settings->max_threads, file_infos.file_names.size());
346	
347	    /// Each stream responsible for closing it's files and store meta
348	    openFilesAndSetPos();
349	
350	    Pipes pipes;
351	    pipes.reserve(max_streams_number);
352	    for (size_t stream_number = 0; stream_number < max_streams_number; ++stream_number)
353	    {
354	        pipes.emplace_back(std::make_shared<FileLogSource>(
355	            *this,
356	            storage_snapshot,
357	            modified_context,
358	            column_names,
359	            getMaxBlockSize(),
360	            getPollTimeoutMillisecond(),
361	            stream_number,
362	            max_streams_number));
363	    }
364	
365	    return Pipe::unitePipes(std::move(pipes));
366	}
